      explanation: { overview: "営業時間拡張の判断。深夜需要と安全管理を定量評価。", tiers: ["無人運営＋AI監視で段階的に拡張する結論。","左に需要（価値）→右に安全管理（リスク）。","左から会員調査→先行事例→安全データ。"], distractorNote: "健康経営やSNS指標は24時間化判断に直接影響しない。" },
