      narrative: { correctReading: "「ビジネス・教育系の2学科で新設、初年度800名」——まず「市場機会は？」→通信制入学者5年で1.6倍・社会人比率78%、中央大も充足110%維持。市場機会は明白。次に「自社の勝ち筋は？」→現職120名のうち通信制対応可教員80名＋年20名特任追加で運営可能、社会人特化で他大学と差別化。市場機会と自社強みを噛み合わせる。", argSwap: { reading: "自社勝ち筋→市場機会の順だと「教員が心配。でも社会人需要はある」と内向き。", contrast: "市場機会→自社勝ち筋：「需要が伸びる。自社はこう勝つ」＝市場開拓\n自社勝ち筋→市場機会：「自社にできる。市場もあるはず」＝自前主義\n\n市場開拓は機会を先に示す。" } }
