        { id: "c2", text: "国内eスポーツ市場は5年で4倍、関連グッズ・スポンサー・施設市場合計で年800億規模", type: "evidence", tier: 2, phrase: "5年で4倍・関連800億", reason: "市場機会の定量根拠。最重要。" },
        { id: "c4", text: "アシックスはeスポーツチームスポンサー＋専用ウェアで5年で関連売上を80億規模に育成", type: "evidence", tier: 2, phrase: "アシックスで80億化", reason: "先行事例。中央で補強。" },
        { id: "c6", text: "既存スポーツ顧客の若年層調査でeスポーツ関心63%、両立購入意向42%、カニバリ試算3%以下", type: "evidence", tier: 2, phrase: "両立意向42%・カニバリ3%", reason: "両立性の自社データ。右端。" },
        { id: "d1", text: "ゲーム配信プラットフォーム視聴時間が世界で増加", type: "distractor", tier: -1, phrase: "ゲーム配信増", reason: "別市場の話で、参入判断の直接根拠にはならない。" },
        { id: "d2", text: "国内オリンピック選手の活躍が話題に", type: "distractor", tier: -1, phrase: "五輪選手活躍", reason: "話題一般の話で、eスポーツ判断には使えない。" }
